+        assertFalse(
+            client(REMOTE_CLUSTER_2).admin()
+                .cluster()
+                .prepareHealth(remoteIndex2)
+                .setWaitForYellowStatus()
+                .setTimeout(TimeValue.timeValueSeconds(10))
+                .get()
+                .isTimedOut()
