+        Map<String, Object> clusterInfo = new HashMap<>();
+        clusterInfo.put("local.index", localIndex);
+
+        clusterInfo.put("remote1.index", remoteIndex1);
+        clusterInfo.put("remote1.skip_unavailable", skipUnavailable1);
