+            for (int i = 0; i < numDocs; i++) {
+                String id = Integer.toString(between(1, 50));
+                String value = "v-" + between(1, 1000);
+                indexedDocs.put(id, value);
+                pendingIds.add(id);
+                bulk.add(new IndexRequest("test").id(id).source("f", value));
+            }
+            assertNoFailures(bulk.get());
